{
  "incident_id": "mitre-T1041",
  "telemetry_version": 1,
  "assessment": "Confirmed active exfiltration from critical host web-01 to c2-01. Policy restricts isolation of critical assets, but block_egress to the C2 destination is permitted. Immediate containment of the exfiltration channel is required.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Evidence M1 confirms unauthorized data exfiltration from web-01 to c2-01. The policy permits block_egress on c2-01. This action interrupts the active exfiltration path without isolating the critical host web-01, preserving its availability while stopping the data loss."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "c2-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Blocks the confirmed exfiltration channel from the critical host web-01 to the attacker destination c2-01. This minimizes attacker spread and stops data loss while preserving the critical service on web-01, which cannot be isolated per policy.",
      "ttl_minutes": 15,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact on web-01 services dependent on c2-01 is unknown as dependency data is not provided. Blocking egress to c2-01 may disrupt legitimate services if any exist, though evidence suggests the channel is attacker-controlled."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

