{
  "incident_id": "mitre-T1021-002",
  "telemetry_version": 1,
  "assessment": "Confirmed lateral movement via SMB from workstation-01 to peer hosts. The threat is active and spreading malicious files. Containment is required to stop the spread while preserving forensic evidence and management channels.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Evidence M1 confirms active lateral movement (SMB administrative-share access) from workstation-01 spreading malicious files. This requires immediate containment to stop the spread. Isolate_host is the most effective control to fully stop lateral movement and exfiltration vectors from this host, and it is a legal action for this target under the policy."
    }
  ],
  "actions": [
    {
      "kind": "isolate_host",
      "target_id": "workstation-01",
      "scope_host_ids": [],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Isolating workstation-01 stops the confirmed SMB lateral movement and file spreading to peer hosts. This action preserves the management and evidence_collector channels as required. The availability impact on the host is total loss of connectivity, but this is necessary to contain the active threat. No other legal controls (restrict_lateral) are sufficient to stop the active spreading as effectively as isolation in this context, and isolate_host is explicitly permitted.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact on workstation-01 is total isolation, which is necessary for containment. Impact on peer hosts is unknown as they are not directly isolated but are sources of further investigation.",
    "Forensic evidence on workstation-01 is preserved by the isolation (network state) but live memory/disk state is not explicitly captured by this action alone; however, the action does not destroy evidence."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

